  "revision_action": "strengthen",
  "supportive_card_ids": ["C55", "C75", "C03", "C19"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C55", "C75", "C03", "C19"],
  "claims": [
    {
      "claim": "L3's closest supplied analog (M03, LCB01-0371), an oxazolidinone sharing the query's 3-fluoro-4-(2-oxooxazolidin-5-yl)phenyl core and pyridine linker, showed substantial oral systemic exposure in healthy subjects: AUC0-∞ 18,846.5 ng·h/mL and AUC0-last 18,636.27 ng·h/mL after a single 800 mg PO dose.",
      "card_ids": ["C55", "C75"]
    },
    {
      "claim": "No L3 record provides an affirmative F < 20% outcome for the query or a matched analog; the close-analog records are oral AUC/Cmax measurements without an IV comparator, so they support absorption/exposure direction without quantifying absolute bioavailability.",
      "card_ids": ["C55", "C75"]
    },
    {
      "claim": "Prior L1/L2 gold-context records remain supportive, with all point estimates at or above ~27% and no affirmative low-F evidence; the query's tetrazole-for-triazole change relative to M03 is a conservative heteroaryl swap that does not introduce a known low-F liability.",
      "card_ids": ["C03", "C19", "C55", "C75"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C55", "C75"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query or an exact matched analog is present; L3 provides AUC/Cmax only, without an IV comparator.",
    "The closest L3 analog M03 (LCB01-0371) differs from the query by the heteroaryl group (triazole vs tetrazole), so transfer is structural rather than direct.",
    "No query-specific solubility, permeability, gut-wall efflux, or first-pass metabolism data are available at this level.",
    "High TPSA (106 Å²) and HBA count (8) remain permeability caveats, but no affirmative evidence links them to F < 20%."
  ],
  "decision_summary": "Predicted high: L3 oral exposure records add supportive context through the close oxazolidinone analog M03 (LCB01-0371) with substantial oral AUC after 800 mg PO, and no L3 record provides affirmative evidence for F < 20%; the prior high prediction is strengthened with moderate confidence."
}

